131: memory_partition_unit::arbitration_metadata::arbitration_metadata(
132:     const memory_config *config)
133:     : m_last_borrower(config->m_n_sub_partition_per_memory_channel - 1),
134:       m_private_credit(config->m_n_sub_partition_per_memory_channel, 0),
135:       m_shared_credit(0) {
136:   // each sub partition get at least 1 credit for forward progress
137:   // the rest is shared among with other partitions
138:   m_private_credit_limit = 1;
139:   m_shared_credit_limit = config->gpgpu_frfcfs_dram_sched_queue_size +
140:                           config->gpgpu_dram_return_queue_size -
141:                           (config->m_n_sub_partition_per_memory_channel - 1);
142:   if (config->seperate_write_queue_enabled)
143:     m_shared_credit_limit += config->gpgpu_frfcfs_dram_write_queue_size;
144:   if (config->gpgpu_frfcfs_dram_sched_queue_size == 0 or
145:       config->gpgpu_dram_return_queue_size == 0) {
146:     m_shared_credit_limit =
147:         0;  // no limit if either of the queue has no limit in size
148:   }
149:   assert(m_shared_credit_limit >= 0);
150: }
