152: bool memory_partition_unit::arbitration_metadata::has_credits(
153:     int inner_sub_partition_id) const {
154:   int spid = inner_sub_partition_id;
155:   if (m_private_credit[spid] < m_private_credit_limit) {
156:     return true;
157:   } else if (m_shared_credit_limit == 0 ||
158:              m_shared_credit < m_shared_credit_limit) {
159:     return true;
160:   } else {
161:     return false;
162:   }
163: }
