164: bool dram_t::full(bool is_write) const {
165:   if (m_config->scheduler_type == DRAM_FRFCFS) {
166:     if (m_config->gpgpu_frfcfs_dram_sched_queue_size == 0) return false;
167:     if (m_config->seperate_write_queue_enabled) {
168:       if (is_write)
169:         return m_frfcfs_scheduler->num_write_pending() >=
170:                m_config->gpgpu_frfcfs_dram_write_queue_size;
171:       else
172:         return m_frfcfs_scheduler->num_pending() >=
173:                m_config->gpgpu_frfcfs_dram_sched_queue_size;
174:     } else
175:       return m_frfcfs_scheduler->num_pending() >=
176:              m_config->gpgpu_frfcfs_dram_sched_queue_size;
177:   } else
178:     return mrqq->full();
179: }
